    dnp_dht_stats stats=dlm_node_discovery_stats(nodes[0].handle);assert(stats.sent>20 && stats.received>20 && stats.peers==2 && stats.used<=stats.limit);
    /* Independently captured packets must be rejected on replay and in another network. */
    dnp_dht *a=nodes[0].handle,*b=nodes[1].handle;dnp_pending request;assert(!dnp_request(a,&request,records[1].identity,records[2].identity,1,0));uint8_t wire[DNP_WIRE_MAX];dnn_datagram captured={0};for(unsigned i=0;i<100;i++) { captured=dlm_net_udp_recv(b->socket,wire,sizeof wire);if(!captured.io.status) break;(void)dlm_net_wait(b->socket,1,10,NULL); }assert(!captured.io.status);assert(!dlm_net_udp_send(a->socket,b->local,wire,captured.io.count).status);assert(!dnp_dht_receive(b,NULL,0).status);assert(!dlm_net_udp_send(a->socket,b->local,wire,captured.io.count).status);assert(dnp_dht_receive(b,NULL,0).status==13);b->count=0;assert(!dlm_net_udp_send(a->socket,b->local,wire,captured.io.count).status);assert(dnp_dht_receive(b,NULL,0).status==13);wire[8]^=1;assert(!dlm_net_udp_send(a->socket,b->local,wire,captured.io.count).status);assert(dnp_dht_receive(b,NULL,0).status==DNN_INVALID);
